using Godot;
using System;
public partial class MigrationScene {
 void ArtStructure(Node3D node,BuildPiece p){var d=p.Def;foreach(Node c in node.GetChildren())if(c is MeshInstance3D mesh)mesh.MaterialOverride=Textured(Wood,0,.65f);if(p.Kind==0){foreach(Node c in node.GetChildren())if(c is MeshInstance3D m)m.MaterialOverride=Material(new Color(.30f,.34f,.29f));Box(node,new Vector3(0,(float)d.H+.015f,0),new Vector3((float)d.W,.03f,(float)d.D),Wood);}if(p.Kind is 2 or 3){for(float y=.25f;y<d.H;y+=.25f)Box(node,new Vector3(0,y,-(float)d.D/2-.01f),new Vector3((float)d.W,.02f,.02f),new Color(.15f,.12f,.085f));for(int side=-1;side<=1;side+=2){Box(node,new Vector3(side*((float)d.W/2-.07f),(float)d.H/2,-(float)d.D/2-.02f),new Vector3(.12f,(float)d.H,.05f),Wood*.7f);for(float y=.2f;y<d.H;y+=.5f)Ellipsoid(node,new Vector3(side*((float)d.W/2-.07f),y,-(float)d.D/2-.055f),new Vector3(.018f,.018f,.008f),Steel);}}if(p.Kind is 1 or 7){for(float x=-(float)d.W/2+.25f;x<d.W/2;x+=.25f)Box(node,new Vector3(x,(float)d.H+.015f,0),new Vector3(.015f,.015f,(float)d.D),Ink);}if(p.Kind==4){for(float y=.15f;y<d.H;y+=.65f)Bevel(node,new Vector3(0,y,0),new Vector3((float)d.W+.025f,.07f,(float)d.D+.025f),Steel);}}
 void DressChests(){for(int i=0;i<3;i++){var p=new Vector3((float)ExpeditionDungeon.ChestX[i],0,(float)ExpeditionDungeon.ChestZ[i]);Bevel(dungeonRoot,p+new Vector3(0,.78f,0),new Vector3(.94f,.15f,.84f),Wood);for(int s=-1;s<=1;s+=2)Box(dungeonRoot,p+new Vector3(s*.3f,.4f,-.425f),new Vector3(.045f,.75f,.025f),Steel);Bevel(dungeonRoot,p+new Vector3(0,.62f,-.44f),new Vector3(.12f,.13f,.04f),new Color(.63f,.53f,.27f));}}
}
